/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    long long ans = 0;
    long long check(TreeNode* node, long long lo, long long hi) {
        if (!node) return 0;
        if (node->val <= lo || node->val >= hi) return LLONG_MIN;
        long long l = check(node->left, lo, node->val);
        long long r = check(node->right, node->val, hi);
        if (l == LLONG_MIN || r == LLONG_MIN) return LLONG_MIN;
        return l + r + node->val;
    }
    void collect(TreeNode* node) {
        if (!node) return;
        long long s = check(node, LLONG_MIN, LLONG_MAX);
        if (s != LLONG_MIN) ans = max(ans, s);
        collect(node->left);
        collect(node->right);
    }
    int maxSumBST(TreeNode* root) {
        collect(root);
        return (int)ans;
    }
};

