/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val; this.left = left; this.right = right;
 *     }
 * }
 */
class Solution {
    private long ans = 0;
    private Long check(TreeNode node, long lo, long hi) {
        if (node == null) return 0L;
        if (node.val <= lo || node.val >= hi) return null;
        Long l = check(node.left, lo, node.val);
        Long r = check(node.right, node.val, hi);
        if (l == null || r == null) return null;
        return l + r + node.val;
    }
    private void collect(TreeNode node) {
        if (node == null) return;
        Long s = check(node, Long.MIN_VALUE, Long.MAX_VALUE);
        if (s != null) ans = Math.max(ans, s);
        collect(node.left);
        collect(node.right);
    }
    public int maxSumBST(TreeNode root) {
        collect(root);
        return (int) ans;
    }
}

