# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxSumBST(self, root: Optional[TreeNode]) -> int:
        self.ans = 0
        INF = float('inf')
        def dfs(node):
            if not node:
                return (True, INF, -INF, 0)
            lbst, lmin, lmax, lsum = dfs(node.left)
            rbst, rmin, rmax, rsum = dfs(node.right)
            if lbst and rbst and lmax < node.val < rmin:
                s = lsum + rsum + node.val
                self.ans = max(self.ans, s)
                return (True, min(lmin, node.val), max(rmax, node.val), s)
            return (False, 0, 0, 0)
        dfs(root)
        return self.ans

