class Solution {
public:
    long long ans = 0;
    array<long long,4> dfs(TreeNode* node) {
        if (!node) return {1, LLONG_MAX, LLONG_MIN, 0};
        auto L = dfs(node->left);
        auto R = dfs(node->right);
        if (L[0] && R[0] && L[2] < node->val && node->val < R[1]) {
            long long s = L[3] + R[3] + node->val;
            ans = max(ans, s);
            return {1, min(L[1], (long long)node->val), max(R[2], (long long)node->val), s};
        }
        return {0, 0, 0, 0};
    }
    int maxSumBST(TreeNode* root) {
        dfs(root);
        return (int)ans;
    }
};

